SELECT

FROM
mold_info mi
where
${params.sqlMap.default}
AND mi.is_deleted = FALSE

    ${params.permissionSql}

ORDER BY


        ${item.field} ${item.sort}


mi.create_time desc

SELECT approve_status AS tabFlag, count(*) AS count FROM mold_info WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status

select id,code,name from mold_info where is_deleted = false and invalid_status = false
AND approve_status =#{params.approveStatus}
AND ( code ILIKE concat('%',#{params.searchKeyword}::text,'%') OR name ILIKE concat('%',#{params.searchKeyword}::text,'%') ) ORDER BY case when code ILIKE concat(#{params.searchKeyword}::text,'%') THEN 1 when code ILIKE concat('%',#{params.searchKeyword}::text) THEN 2 when code ILIKE concat('%',#{params.searchKeyword}::text,'%') THEN 3 end , code
